-- Cần migration 0007 trước. Ảnh đã nằm trên Cloudinary (thư mục f21-hotel, tên xung-quanh-<mã>). Chạy lại không tạo trùng.
--   npx wrangler d1 execute D1 --remote --file db/seeds/anh-tien-ich-xung-quanh.sql
-- Ảnh Wikimedia Commons (giấy phép mở) cho Tiện ích xung quanh: thêm vào Thư viện ảnh, gắn vào địa điểm, ghi công tác giả.
INSERT INTO media (alt, prefix, url, filename, mime_type, filesize, width, height) SELECT 'Tàu lượn siêu tốc màu đỏ ở Thiên đường Bảo Sơn', '', 'https://res.cloudinary.com/lc5xfg4x/image/upload/f_auto,q_auto/f21-hotel/xung-quanh-thien-duong-bao-son.jpg', 'xung-quanh-thien-duong-bao-son.jpg', 'image/jpg', 794589, 1920, 1440 WHERE NOT EXISTS (SELECT 1 FROM media WHERE filename = 'xung-quanh-thien-duong-bao-son.jpg');
DELETE FROM places_rels WHERE path = 'photo' AND parent_id = (SELECT id FROM places WHERE slug = 'thien-duong-bao-son');
INSERT INTO places_rels ("order", parent_id, path, media_id) SELECT 1, p.id, 'photo', m.id FROM places p, media m WHERE p.slug = 'thien-duong-bao-son' AND m.filename = 'xung-quanh-thien-duong-bao-son.jpg';
UPDATE places SET photo_credit = 'Martin Lewison, CC BY 2.0 (Wikimedia Commons)', photo_source = 'https://commons.wikimedia.org/wiki/File:Bao_Son_Paradise_Theme_Park_(49357894926).jpg' WHERE slug = 'thien-duong-bao-son';
